def count_binary_seq(n):
    from math import comb

    def count_sequences(n, k):
        if k < 0 or k > n:
            return 0
        return comb(n, k) ** 2

    result = sum(count_sequences(n, k) for k in range(n + 1))
    return result / 2 ** (n - 1)
