def max_volume(n):
    max_vol = 0
    for x in range(1, n // 3 + 1):
        for y in range(x, (n - x) // 2 + 1):
            z = n - x - y
            vol = x * y * z
            max_vol = vol if vol > max_vol else max_vol
    return max_vol
