import math

def count_Fac(n):
    result = set()
    for i in range(2, int(math.sqrt(n)) + 1):
        count = 0
        if n % i == 0:
            while n % i == 0:
                n //= i
                count += 1
            result.add(count)
    if n > 1:
        result.add(1)
    return len(result)
